#include "AcidEngine.h"
#include <iostream>
#include <stdexcept>
#include <limits>
void check(bool v,const char*message){if(!v)throw std::runtime_error(message);}
void outputCheck(float l,float r){check(std::isfinite(l)&&std::isfinite(r),"Non-finite output during soak");check(std::abs(l)<=.50001f&&std::abs(r)<=.50001f,"Output exceeded -6 dBFS protection ceiling");}
void run(double rate,int seconds){acid::Engine e;e.prepare(rate);const int scenes[]={0,127,175,207,255,223};auto p=acid::scenes[0].values;e.setParameters(p);int stepSamples=(int)(rate*60/128/4),gate=(int)(stepSamples*.6),scene=-1;float maximum=0;double mean=0;int64_t total=(int64_t)(rate*seconds);for(int64_t i=0;i<total;i++){int next=(int)(i/(int64_t)(rate*30))%6;if(next!=scene){scene=next;p=acid::scenes[(size_t)scenes[scene]].values;p[acid::EchoFeedback]=.85f;p[acid::Room]=1;e.setParameters(p);}if(i%128==0)e.setParameters(p);if(i%stepSamples==0){int step=(int)((i/stepSamples)%16);e.note(36+(step%5)*3,.9f,step%4==0,step%3==0,step%5==0);}if(i%stepSamples==gate)e.off();float l,r;e.sample(l,r,128);outputCheck(l,r);maximum=std::max(maximum,std::max(std::abs(l),std::abs(r)));mean+=l;}
 check(maximum>.0001f,"Soak run became silent");check(e.protectionTrips()==0,"Output guard activated during valid factory-scene soak");check(std::abs(mean/total)<.05,"DC accumulation in long run");e.off();double tailEnergy=0;int tailCount=0;for(int i=0;i<(int)(rate*20);i++){float l,r;e.sample(l,r,128);outputCheck(l,r);if(i>=rate*19){tailEnergy+=(double)l*l+(double)r*r;tailCount+=2;}}check(std::sqrt(tailEnergy/std::max(1,tailCount))<.002,"Effect tail did not decay after notes stopped");e.reset();for(int i=0;i<128;i++){float l,r;e.sample(l,r,128);check(l==0&&r==0,"Reset did not silence buffers");}std::cout<<"PASS: "<<seconds<<" audio seconds at "<<rate<<" Hz; peak "<<maximum<<"; zero guard resets; tail decayed\n";}
int main(){try{acid::StableLowpass filter;float x=filter.tick(std::numeric_limits<float>::infinity(),11000,.95f,48000);check(x==0&&filter.failed,"Invalid filter state was not rejected");filter.reset();check(std::isfinite(filter.tick(.5f,1.e9f,.95f,48000)),"Extreme cutoff was not contained");run(44100,30);run(96000,30);run(48000,600);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
